/**
 * An SSO connection for an organization (SAML or Azure AD).
 */
export type SsoConnection = {
    id: number;
    provider: 'saml' | 'azure_ad' | 'oidc';
    /**
     * Server-generated, immutable identifier. Never client-supplied.
     */
    readonly sso_identifier: string;
    name: string;
    /**
     * Additional login domains.
     */
    domains?: Array<SsoConnectionDomain>;
    /**
     * The DNS record the org admin must create to prove ownership of each login domain: a CNAME at <host_prefix>.<domain> pointing to target.
     */
    domain_verification?: {
        record_type: string;
        host_prefix: string;
        target: string;
    };
    /**
     * Whether the connection is active. Read-only.
     */
    readonly active: boolean;
    /**
     * SAML IdP metadata XML (SAML connections only).
     */
    idp_meta?: string | null;
    /**
     * Azure AD tenant ID (Azure AD connections only).
     */
    aad_tenant?: string | null;
    /**
     * Issuer URL of the OpenID Connect (OIDC) provider. Applies to OIDC connections only. The URL must use `https`. Storyblok discovers the authorization, token, and JSON Web Key Set (JWKS) endpoints from it, so you configure no other URL.
     */
    oidc_issuer?: string;
    /**
     * OIDC connections only. Client ID of the application registered for Storyblok with the provider.
     */
    oidc_client_id?: string;
    /**
     * OIDC connections only. Scopes requested at the authorization endpoint; must include `openid`. Empty means the API uses the default `openid` profile email.
     */
    oidc_scope?: Array<string>;
    oidc_claim_mappings?: SsoConnectionOidcClaimMappings;
    /**
     * OIDC connections only, read-only. The redirect URI to register with the identity provider. Register this value as is, because it’s the exact URI that the login path sends.
     */
    readonly oidc_redirect_uri?: string;
    /**
     * OIDC connections only, read-only. Whether Storyblok stores a client secret. The secret itself is never returned.
     */
    readonly client_secret_set?: boolean;
    /**
     * Read-only, org-sourced. Whether email matching is case-insensitive.
     */
    readonly case_insensitive_email_match?: boolean;
    attribute_mappings?: SsoConnectionAttributeMappings;
    /**
     * SAML only. Whether the connection signs the AuthnRequest. Taken from the connection config.
     */
    sign_saml_request?: boolean;
    readonly enforce_sso?: boolean;
    /**
     * Org-sourced. When enabled, Storyblok converts existing email/password users who log in via SSO with a matching email to SSO users. Org-wide setting shared across connections. Writable on update only.
     */
    merge_users?: boolean;
    /**
     * Creation timestamp. Supports ISO 8601.
     */
    created_at?: string;
    /**
     * Latest update timestamp. Supports ISO 8601.
     */
    updated_at?: string;
};

/**
 * Maps IdP assertion attributes to Storyblok user fields.
 */
export type SsoConnectionAttributeMappings = {
    /**
     * First name of a collaborator.
     */
    firstname?: string;
    /**
     * Last name of a collaborator.
     */
    lastname?: string;
    /**
     * Alternative email of a collaborator.
     */
    alt_email?: string;
};

/**
 * An SSO login domain and its DNS verification status.
 */
export type SsoConnectionDomain = {
    name: string;
    /**
     * DNS verification status. Legacy domains not yet tracked as verification rows are grandfathered and report verified.
     */
    status: 'verified' | 'pending' | 'failed';
};

/**
 * Writable fields for creating an SSO connection. provider is required and you can set it only on create; domain is required on create. The API ignores read-only fields (`sso_identifier`, active, etc.) if you supply them.
 */
export type SsoConnectionInput = {
    /**
     * The SSO connection to create.
     */
    sso_connection: {
        /**
         * Identity provider protocol: `saml`, `azure_ad`, or `oidc`.
         */
        provider: 'saml' | 'azure_ad' | 'oidc';
        /**
         * Display name of the SSO connection.
         */
        name?: string;
        /**
         * Additional login domains.
         */
        domains: Array<string>;
        /**
         * SAML only. IdP metadata XML.
         */
        idp_meta?: string;
        /**
         * Azure AD only. Tenant ID.
         */
        aad_tenant?: string;
        /**
         * Issuer URL of the OIDC provider. Applies to OIDC connections only. The URL must use `https`. Storyblok uses it to discover the provider’s endpoints.
         */
        oidc_issuer?: string;
        /**
         * OIDC only. Client ID of the application registered for Storyblok with the provider.
         */
        oidc_client_id?: string;
        /**
         * OIDC only. Scopes requested at the authorization endpoint. Must include `openid`. To use the default `openid` profile email, omit or send an empty list.
         */
        oidc_scope?: Array<string>;
        oidc_claim_mappings?: SsoConnectionOidcClaimMappings;
        attribute_mappings?: SsoConnectionAttributeMappings;
        /**
         * SAML only.
         */
        sign_saml_request?: boolean;
        /**
         * Whether members must sign in through SSO.
         */
        enforce_sso?: boolean;
        /**
         * Org-wide setting: convert existing email/password users to SSO users when they log in via SSO with a matching email.
         */
        merge_users?: boolean;
    };
};

/**
 * Maps Storyblok user fields to `id_token` claims. Applies to OIDC connections only. Each field takes an ordered list of claim names, and Storyblok uses the first one present. An unmapped field uses its standard OIDC claim, if it has one. The object replaces all stored mappings—omit it to keep them. The API rejects unknown field names with a validation error.
 */
export type SsoConnectionOidcClaimMappings = {
    /**
     * Claims that identify the user. The standard claim is `sub`. If you map this field and the token has none of the listed claims, Storyblok refuses the login.
     */
    uid?: Array<string>;
    /**
     * Claims that include the user’s email address. The standard claim is `email`. Storyblok also uses the email to link an existing SCIM-provisioned user. If you map this field and the token has none of the listed claims, Storyblok refuses the login.
     */
    alt_email?: Array<string>;
    /**
     * Claims that include the user’s first name. The standard claim is `given_name`.
     */
    firstname?: Array<string>;
    /**
     * Claims that include the user’s last name. The standard claim is `family_name`.
     */
    lastname?: Array<string>;
    /**
     * Claims that include the user’s full name. The standard claim is `name`. Storyblok splits it into first and last name when the token has neither.
     */
    name?: Array<string>;
    /**
     * Claims that include the user’s groups. Storyblok ignores group claims unless you map this field. When mapped, Storyblok compares the claim values with the external IDs of space roles, as it does for SAML and Azure groups. If the claim is absent, the user gets no roles.
     */
    groups?: Array<string>;
    [key: string]: unknown;
};

export type SsoConnectionResponse = {
    sso_connection: SsoConnection;
};

/**
 * Writable fields for updating an SSO connection. provider is immutable, and the API ignores it if you supply it. The API ignores read-only fields (`sso_identifier`, etc.) if you supply them.
 */
export type SsoConnectionUpdateInput = {
    /**
     * The SSO connection to update.
     */
    sso_connection: {
        /**
         * Display name of the SSO connection.
         */
        name?: string;
        /**
         * Additional login domains.
         */
        domains?: Array<string>;
        /**
         * SAML only. IdP metadata XML.
         */
        idp_meta?: string;
        /**
         * Azure AD only. Tenant ID.
         */
        aad_tenant?: string;
        /**
         * Issuer URL of the OIDC provider. Applies to OIDC connections only. The URL must use `https`.
         */
        oidc_issuer?: string;
        /**
         * OIDC only. Client ID of the application registered for Storyblok with the provider.
         */
        oidc_client_id?: string;
        /**
         * OIDC only. Replaces the stored scopes; must include `openid`. Send an empty list to fall back to the default `openid` profile email.
         */
        oidc_scope?: Array<string>;
        oidc_claim_mappings?: SsoConnectionOidcClaimMappings;
        attribute_mappings?: SsoConnectionAttributeMappings;
        /**
         * SAML only.
         */
        sign_saml_request?: boolean;
        /**
         * Whether members must sign in through SSO.
         */
        enforce_sso?: boolean;
        /**
         * Org-wide setting: convert existing email/password users to SSO users when they log in via SSO with a matching email. Ignored on create.
         */
        merge_users?: boolean;
    };
};

